        max_gap = gap
        best_k = k
print(f"Max gap for constant sequence: {max_gap} for k={best_k}")

def min_dist_to_S(S, x):
    sums = {0}
    for val in x:
        new_sums = set()
        for s in sums:
            new_sums.add(s + val)
        sums.update(new_sums)

    min_d = float('inf')
    for s in sums:
        min_d = min(min_d, abs(s - S))
    return min_d

