import random

def get_min_dist(S, x):
    sums = {0}
    for val in x:
        new_sums = set()
        for s in sums:
            new_sums.add(s + val)
        sums.update(new_sums)

    min_d = float('inf')
    for s in sums:
        if s == S: return 0
        min_d = min(min_d, abs(s - S))
    return min_d

