def find_sequence(S, min_dist_target, max_val):
    # We want to find a sequence x such that for all subset sums T, |T - S| >= min_dist_target.
    # This means T <= S - min_dist_target or T >= S + min_dist_target.

    forbidden_low = S - min_dist_target + 1
    forbidden_high = S + min_dist_target - 1

    # We use backtracking to find the sequence.
    # x_i can be from 1 to max_val.

    def is_valid(current_sums, new_val):
        for s in current_sums:
            if forbidden_low <= s + new_val <= forbidden_high:
                return False
        return True

    def backtrack(current_sums, current_sum, sequence):
        if current_sum >= S:
            # Check if any subset sum is in the forbidden range
            # Actually, is_valid already checks this.
            return sequence

        # Try values for the next element. 
        # To keep the sum growing and avoid the forbidden range,
        # we should try larger values first.
        for val in range(max_val, 0, -1):
            if is_valid(current_sums, val):
                # Update subset sums
                new_sums = set(current_sums)
                for s in current_sums:
                    new_sums.add(s + val)

                res = backtrack(new_sums, current_sum + val, sequence + [val])
                if res:
                    return res
        return None

    return backtrack({0}, 0, [])

S = 1810
for target in [47, 48, 49]:
    seq = find_sequence(S, target, 100)
    print(f"Target {target}: {seq}")

def find_sequence_bitset(S, min_dist_target, max_val):
    forbidden_low = S - min_dist_target + 1
    forbidden_high = S + min_dist_target - 1

    # Mask for the forbidden range
    # The bits from forbidden_low to forbidden_high should be 0.
    # mask = ((1 << (forbidden_high + 1)) - 1) ^ ((1 << forbidden_low) - 1)
    # Wait, it's easier to just check if (sums & mask) == 0.
    mask = ((1 << (forbidden_high + 1)) - 1) & ~((1 << forbidden_low) - 1)

    def backtrack(sums, current_sum, sequence):
        if current_sum >= S:
            return sequence

        # We only need to try values that could potentially jump over the gap
        # or keep the sums below the gap.
        # Try values from max_val down to 1.
        for val in range(max_val, 0, -1):
            new_sums = sums | (sums << val)
            if not (new_sums & mask):
                res = backtrack(new_sums, current_sum + val, sequence + [val])
                if res:
                    return res
        return None

    return backtrack(1, 0, [])

S = 1810
for target in [47, 48, 49]:
    seq = find_sequence_bitset(S, target, 100)
    print(f"Target {target}: {seq}")

def get_max_min_dist(S, max_val):
    best_d = 0
    for k in range(1, max_val + 1):
        rem = S % k
        d = min(rem, k - rem)
        if d > best_d:
            best_d = d
    return best_d

print(get_max_min_dist(1810, 100))
